import shutil, openpyxl
from openpyxl.utils import column_index_from_string

shutil.copy(INIT, OUT)
vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)
ws = wb.active
vws = vals[ws.title]

def norm(x):
    if x is None:
        return None
    if isinstance(x, bool):
        return None
    if isinstance(x, (int, float)):
        try:
            if x != x:
                return None
        except Exception:
            pass
        if isinstance(x, float) and x.is_integer():
            return int(x)
        return x
    if isinstance(x, str):
        s = x.strip()
        if not s:
            return None
        try:
            f = float(s)
            if f.is_integer():
                return int(f)
            return f
        except Exception:
            return s
    return x

def no_score(x):
    n = norm(x)
    if n is None:
        return True
    if isinstance(n, (int, float)):
        return n == 0
    return False

t_col = column_index_from_string('T')
cb_col = column_index_from_string('CB')
cc_col = column_index_from_string('CC')
d_col = column_index_from_string('D')
e_col = column_index_from_string('E')
f_col = column_index_from_string('F')

def t_value(row):
    n = norm(vws.cell(row=row, column=t_col).value)
    if n is not None and not (isinstance(n, (int, float)) and n == 0):
        return n
    # fallback for triple score if T cached blank/zero
    d = norm(vws.cell(row=row, column=d_col).value)
    e = norm(vws.cell(row=row, column=e_col).value)
    f = norm(vws.cell(row=row, column=f_col).value)
    if isinstance(d, (int, float)) and isinstance(e, (int, float)) and isinstance(f, (int, float)):
        if d == e == f and d > 0:
            return d
    return None

matches = {}
for r in range(2, 601):
    v = t_value(r)
    if v is None:
        continue
    # If v is nonnumeric string, still could match? But scores numeric. To avoid matching text, only numeric?
    # The formula would match text if CB text. But CB scores numeric. Use numeric only.
    if isinstance(v, (int, float)):
        matches.setdefault(v, []).append(r)
    else:
        # include nonnumeric just in case? Could cause unexpected. But if CB nonnumeric, maybe.
        matches.setdefault(v, []).append(r)

cb_vals = {}
for r in range(2, 34):
    cb_vals[r] = vws.cell(row=r, column=cb_col).value

# If CB appears completely empty (no cached values), optionally compute from T? Maybe not.
# But we can detect if all no_score and then compute sorted T scores to be robust.
if all(no_score(cb_vals[r]) for r in cb_vals):
    # compute CB as top 32 T scores descending
    all_t = []
    for r in range(2, 601):
        v = t_value(r)
        if isinstance(v, (int, float)) and v > 0:
            all_t.append(v)
    all_t.sort(reverse=True)
    for i, r in enumerate(range(2, 34)):
        if i < len(all_t):
            cb_vals[r] = all_t[i]
        else:
            cb_vals[r] = 0

for r in range(2, 34):
    cb = cb_vals[r]
    if no_score(cb):
        ws.cell(row=r, column=cc_col).value = None
        continue
    ncb = norm(cb)
    k = 0
    for rr in range(2, r+1):
        if norm(cb_vals[rr]) == ncb:
            k += 1
    lst = matches.get(ncb, [])
    if k <= len(lst):
        ws.cell(row=r, column=cc_col).value = int(lst[k-1])
    else:
        # As a last resort, search beyond 600? maybe not.
        ws.cell(row=r, column=cc_col).value = None

wb.save(OUT)
print('done', [(r, cb_vals[r], ws.cell(row=r, column=cc_col).value) for r in range(2, 8)])
